[ExtensionOf(classStr(LedgerJournalPeriodicCopy))]
final class AVALedgerJournalPeriodicCopy_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
void journalVoucherCopy()
{
    next journalVoucherCopy();
    AVALedgerJournalPeriodicCopyTmp            ledgerJournalPeriodicCopyTmp;
    LedgerJournalTrans                      ledgerJournalTrans;
    LedgerJOurnalTrans                      ledgerJournalTransPeriodic;

    while select ledgerJournalTrans
        where ledgerJournalTrans.JournalNum == ledgerJournalEngine.ledgerJournalTable().Journalnum
        join ledgerJournalPeriodicCopyTmp
            where ledgerJournalPeriodicCopyTmp.LedgerJournalTransRecIdNew == ledgerJournalTrans.RecId
       join ledgerJournalTransPeriodic
            where ledgerJournalTransPeriodic.RecId == ledgerJournalPeriodicCopyTmp.LedgerJournalTransRecIdOld
               && (ledgerJournalTransPeriodic.AVAEndDate < endDate    && ledgerJournalTransPeriodic.AVAEndDate != dateNull())     
    {
        ttsbegin;
        ledgerJournalTrans.selectForUpdate(true);
        ledgerJournalTrans.delete();

        ledgerJournalPeriodicCopyTmp.selectForUpdate(true);
        ledgerJournalPeriodicCopyTmp.delete();
        ttscommit;
    }


}
